const INTEGER_PATTERN = /^[+-]?[0-9](?:_?[0-9])*$/;

function getProgramName(scriptPath) {
  if (!scriptPath) {
    return "test3.mjs";
  }

  const normalizedPath = scriptPath.replace(/\\/g, "/");
  const parts = normalizedPath.split("/");
  return parts[parts.length - 1] || "test3.mjs";
}

function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function formatHelp(programName) {
  return `${formatUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

function formatPythonStringLiteral(value) {
  let literal = "'";

  for (const character of value) {
    const codePoint = character.codePointAt(0);

    if (character === "\\") {
      literal += "\\\\";
    } else if (character === "'") {
      literal += "\\'";
    } else if (character === "\t") {
      literal += "\\t";
    } else if (character === "\n") {
      literal += "\\n";
    } else if (character === "\r") {
      literal += "\\r";
    } else if (codePoint >= 0x20 && codePoint <= 0x7e) {
      literal += character;
    } else if (codePoint <= 0xff) {
      literal += `\\x${codePoint.toString(16).padStart(2, "0")}`;
    } else if (codePoint <= 0xffff) {
      literal += `\\u${codePoint.toString(16).padStart(4, "0")}`;
    } else {
      literal += `\\U${codePoint.toString(16).padStart(8, "0")}`;
    }
  }

  return `${literal}'`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}\n`;
}

function createErrorResponse(programName, message) {
  return {
    exitCode: 2,
    status: "error",
    stream: "stderr",
    text: formatError(programName, message),
  };
}

function isPythonIntToken(value) {
  return INTEGER_PATTERN.test(value);
}

function parsePythonInt(value) {
  if (!isPythonIntToken(value)) {
    return null;
  }

  return BigInt(value.replace(/_/g, ""));
}

function isMissingValueToken(value) {
  return value.startsWith("-") && !isPythonIntToken(value);
}

function parseOptionValue(programName, optionName, rawValue) {
  const parsedValue = parsePythonInt(rawValue);

  if (parsedValue === null) {
    return createErrorResponse(
      programName,
      `argument ${optionName}: invalid int value: ${formatPythonStringLiteral(rawValue)}`
    );
  }

  return {
    status: "ok",
    value: parsedValue,
  };
}

export function parseCommandLine(argv = process.argv) {
  const programName = getProgramName(argv[1]);
  const tokens = argv.slice(2);
  const parsedValues = {};
  const unrecognizedArguments = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === "-h" || token === "--help") {
      return {
        exitCode: 0,
        status: "help",
        stream: "stdout",
        text: formatHelp(programName),
      };
    }

    if (token === "--") {
      unrecognizedArguments.push(...tokens.slice(index + 1));
      break;
    }

    if (token === "--a" || token === "--b") {
      const rawValue = tokens[index + 1];

      if (rawValue === undefined || isMissingValueToken(rawValue)) {
        return createErrorResponse(programName, `argument ${token}: expected one argument`);
      }

      const parsedOption = parseOptionValue(programName, token, rawValue);

      if (parsedOption.status !== "ok") {
        return parsedOption;
      }

      parsedValues[token.slice(2)] = parsedOption.value;
      index += 1;
      continue;
    }

    if (token.startsWith("--a=") || token.startsWith("--b=")) {
      const separatorIndex = token.indexOf("=");
      const optionName = token.slice(0, separatorIndex);
      const rawValue = token.slice(separatorIndex + 1);
      const parsedOption = parseOptionValue(programName, optionName, rawValue);

      if (parsedOption.status !== "ok") {
        return parsedOption;
      }

      parsedValues[optionName.slice(2)] = parsedOption.value;
      continue;
    }

    unrecognizedArguments.push(token);
  }

  const missingArguments = [];

  if (parsedValues.a === undefined) {
    missingArguments.push("--a");
  }

  if (parsedValues.b === undefined) {
    missingArguments.push("--b");
  }

  if (missingArguments.length > 0) {
    return createErrorResponse(
      programName,
      `the following arguments are required: ${missingArguments.join(", ")}`
    );
  }

  if (unrecognizedArguments.length > 0) {
    return createErrorResponse(
      programName,
      `unrecognized arguments: ${unrecognizedArguments.join(" ")}`
    );
  }

  return {
    status: "ok",
    values: {
      a: parsedValues.a,
      b: parsedValues.b,
    },
  };
}

