#!/usr/bin/env node
import { parseTest3Args } from "./lib/cli.mjs";
import {
  buildTwoByteStruct,
  FormatFieldError,
  formatConstructTrace,
} from "./lib/byte_struct.mjs";
import { formatPythonBytesLiteral } from "./lib/python_bytes.mjs";

function getScriptStem(scriptPath) {
  if (!scriptPath) {
    return "test3";
  }

  const normalized = scriptPath.replace(/\\/g, "/");
  const baseName = normalized.split("/").pop() || normalized;
  return baseName.replace(/\.[^.]+$/, "") || baseName;
}

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  const parsed = parseTest3Args(argv, scriptPath);

  if (!parsed.ok) {
    if (parsed.stdout) {
      process.stdout.write(parsed.stdout);
    }

    if (parsed.stderr) {
      process.stderr.write(parsed.stderr);
    }

    process.exitCode = parsed.code;
    return;
  }

  try {
    const data = buildTwoByteStruct({
      field1: parsed.values.a,
      field2: parsed.values.b,
    });

    console.log(formatPythonBytesLiteral(data));
  } catch (error) {
    if (error instanceof FormatFieldError) {
      process.stderr.write(
        formatConstructTrace(error, getScriptStem(scriptPath)),
      );
      process.exitCode = 1;
      return;
    }

    throw error;
  }
}

main();

